#!/usr/bin/env python3
'''
S.U.N. - one-file setup + launcher for any local AI.
Run this ONE file. It writes everything, installs what's missing,
makes sure you have an AI model, starts the pieces, and opens the GUI.
Works with WHATEVER models you have in Ollama - not tied to any one model.
Runs 100% on your computer. Nothing is sent anywhere.
'''
import os, sys, time, socket, base64, platform, subprocess, webbrowser, json, urllib.request
from pathlib import Path

HERE = Path(__file__).resolve().parent
GUI = HERE / "SUN.html"
SENSORS = HERE / "sun_sensors.py"
MEMORY = HERE / "sun_memory.py"
OLLAMA_PORT = 11434
SENSOR_PORT = 11435
MEMORY_PORT = 11436
EMBED_MODEL = "nomic-embed-text"
STARTER_MODEL = "llama3.1:8b"
IS_WIN = platform.system() == "Windows"

SUN_HTML_B64 = ""
SENSORS_SRC = r'''#!/usr/bin/env python3
"""
S.U.N. sensor helper.
Reads REAL hardware stats and serves them to the SUN.html dashboard.

Run it once, leave it running in a terminal:
    pip install psutil
    python sun_sensors.py

It listens on http://localhost:11435/stats and returns live JSON.
Anything a sensor can't read comes back as null -> the GUI shows a dash.
Nothing here is faked.

CPU/GPU load, RAM, and GPU temp/VRAM work on Windows and Linux.
CPU *temperature* reads on Linux (needs lm-sensors) and is often unavailable
on Windows via Python -> shows as a dash there. That's a real limitation,
not a bug.
"""

import json
import shutil
import subprocess
from http.server import BaseHTTPRequestHandler, HTTPServer

try:
    import psutil
except ImportError:
    raise SystemExit("Missing psutil. Run:  pip install psutil")

PORT = 11435
NVIDIA_SMI = shutil.which("nvidia-smi")


def read_gpu():
    """RTX 4080 Super via nvidia-smi. Returns util%, temp C, vram used/total MB."""
    if not NVIDIA_SMI:
        return {"gpu": None, "gpu_temp": None, "vram_used": None, "vram_total": None}
    try:
        out = subprocess.run(
            [NVIDIA_SMI,
             "--query-gpu=utilization.gpu,temperature.gpu,memory.used,memory.total",
             "--format=csv,noheader,nounits"],
            capture_output=True, text=True, timeout=2
        ).stdout.strip().splitlines()[0]
        util, temp, vused, vtotal = [x.strip() for x in out.split(",")]
        return {
            "gpu": float(util),
            "gpu_temp": float(temp),
            "vram_used": float(vused),   # MB
            "vram_total": float(vtotal), # MB
        }
    except Exception:
        return {"gpu": None, "gpu_temp": None, "vram_used": None, "vram_total": None}


def read_cpu_temp():
    """Linux + lm-sensors. AMD 7950X shows under k10temp. Null if unreadable."""
    fn = getattr(psutil, "sensors_temperatures", None)
    if not fn:
        return None
    try:
        temps = fn()
        for key in ("k10temp", "coretemp", "zenpower", "acpitz"):
            if key in temps and temps[key]:
                # prefer a package/tctl-style reading, else first entry
                for e in temps[key]:
                    if e.label in ("Tctl", "Tdie", "Package id 0"):
                        return round(e.current, 1)
                return round(temps[key][0].current, 1)
        # fall back to whatever exists
        for arr in temps.values():
            if arr:
                return round(arr[0].current, 1)
    except Exception:
        pass
    return None


def read_stats():
    vm = psutil.virtual_memory()
    stats = {
        "cpu": psutil.cpu_percent(interval=None),        # %
        "cpu_temp": read_cpu_temp(),                     # C or null
        "ram_used": round(vm.used / 1e9, 1),             # GB
        "ram_total": round(vm.total / 1e9, 1),           # GB
        "ram_pct": vm.percent,                           # %
    }
    stats.update(read_gpu())
    return stats


class Handler(BaseHTTPRequestHandler):
    def _allowed_origin(self):
        o = self.headers.get("Origin")
        if o is None or o == "null": return "null"
        if o.startswith("http://localhost") or o.startswith("http://127.0.0.1") or o.startswith("https://localhost"):
            return o
        return None

    def _cors(self):
        allow = self._allowed_origin() or "null"
        self.send_header("Access-Control-Allow-Origin", allow)
        self.send_header("Access-Control-Allow-Methods", "GET, OPTIONS")

    def do_OPTIONS(self):
        self.send_response(204); self._cors(); self.end_headers()

    def do_GET(self):
        if self._allowed_origin() is None:   # refuse other websites
            self.send_response(403); self.end_headers(); return
        if self.path.startswith("/stats"):
            body = json.dumps(read_stats()).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self._cors()
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_response(404); self._cors(); self.end_headers()

    def log_message(self, *a):
        pass  # quiet


if __name__ == "__main__":
    psutil.cpu_percent(interval=None)  # prime the counter
    gpu = "nvidia-smi found" if NVIDIA_SMI else "nvidia-smi NOT found (GPU stats will be blank)"
    print(f"S.U.N. sensor helper on http://localhost:{PORT}/stats  [{gpu}]")
    print("Leave this running. Ctrl+C to stop.")
    HTTPServer(("127.0.0.1", PORT), Handler).serve_forever()
'''
MEMORY_SRC = r'''#!/usr/bin/env python3
"""
S.U.N. memory service.
Sits between the GUI and Ollama. Every exchange is saved to a real database
on disk. Before each reply it pulls back the most relevant past bits (by
meaning, not just recency) and a running "core profile" of you, and feeds
them to the model. This is how S.U.N. remembers.

Nothing lives in the model itself -- it all lives in sun_memory.db next to
this file, so it survives restarts. Cap is 60 GB (functionally unlimited for
text). If the embedding model or DB ever fails, chat still works; memory just
falls back to recent-history only.

Runs on http://localhost:11436  (the GUI points its chat here).
"""
import json, os, sqlite3, math, threading, urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

OLLAMA = "http://127.0.0.1:11434"
PORT = 11436
EMBED_MODEL = "nomic-embed-text"
DB = Path(__file__).resolve().parent / "sun_memory.db"
MAX_BYTES = 60 * 1024**3          # 60 GB cap (you'll never hit it with text)
TOPK = 6                          # relevant memories pulled per turn
RECENT = 4                        # most-recent messages always included
PROFILE_EVERY = 8                 # rebuild core profile every N assistant replies

_lock = threading.Lock()

def db():
    c = sqlite3.connect(DB)
    c.execute("""CREATE TABLE IF NOT EXISTS messages(
        id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, role TEXT, content TEXT, emb TEXT)""")
    c.execute("""CREATE TABLE IF NOT EXISTS kv(k TEXT PRIMARY KEY, v TEXT)""")
    return c

def get_profile():
    try:
        c = db(); r = c.execute("SELECT v FROM kv WHERE k='profile'").fetchone(); c.close()
        return r[0] if r else ""
    except Exception:
        return ""

def set_profile(text):
    try:
        c = db(); c.execute("INSERT OR REPLACE INTO kv(k,v) VALUES('profile',?)", (text,)); c.commit(); c.close()
    except Exception:
        pass

def ollama_post(path, payload, stream=False):
    req = urllib.request.Request(OLLAMA + path, data=json.dumps(payload).encode(),
                                 headers={"Content-Type": "application/json"})
    return urllib.request.urlopen(req, timeout=600)

def embed(text):
    """Return a vector for text, trying both ollama embedding endpoints. None on failure."""
    text = (text or "").strip()
    if not text:
        return None
    try:  # newer ollama
        r = ollama_post("/api/embed", {"model": EMBED_MODEL, "input": text})
        d = json.loads(r.read())
        if "embeddings" in d and d["embeddings"]:
            return d["embeddings"][0]
        if "embedding" in d:
            return d["embedding"]
    except Exception:
        pass
    try:  # older ollama
        r = ollama_post("/api/embeddings", {"model": EMBED_MODEL, "prompt": text})
        d = json.loads(r.read())
        return d.get("embedding")
    except Exception:
        return None

def cosine(a, b):
    if not a or not b: return -1
    s = sum(x*y for x, y in zip(a, b))
    na = math.sqrt(sum(x*x for x in a)); nb = math.sqrt(sum(y*y for y in b))
    return s/(na*nb) if na and nb else -1

def save(role, content, emb):
    if not content: return
    with _lock:
        try:
            c = db()
            c.execute("INSERT INTO messages(ts,role,content,emb) VALUES(?,?,?,?)",
                      (__import__("time").time(), role, content, json.dumps(emb) if emb else None))
            c.commit()
            # 60GB safeguard (never fires for text, but honest)
            if DB.exists() and DB.stat().st_size > MAX_BYTES:
                c.execute("DELETE FROM messages WHERE id IN (SELECT id FROM messages ORDER BY id LIMIT 200)")
                c.commit()
            c.close()
        except Exception:
            pass

def retrieve(query_emb):
    """Top-K past messages by meaning, plus the most recent few. Returns list of dicts."""
    out, seen = [], set()
    try:
        c = db()
        rows = c.execute("SELECT id,role,content,emb FROM messages ORDER BY id DESC LIMIT 4000").fetchall()
        c.close()
    except Exception:
        return out
    # recent
    for r in rows[:RECENT]:
        if r[0] not in seen:
            seen.add(r[0]); out.append({"role": r[1], "content": r[2], "why": "recent"})
    # semantic
    if query_emb:
        scored = []
        for r in rows:
            if r[3]:
                try: e = json.loads(r[3])
                except Exception: continue
                scored.append((cosine(query_emb, e), r))
        scored.sort(key=lambda x: x[0], reverse=True)
        for sc, r in scored[:TOPK]:
            if r[0] not in seen and sc > 0.3:
                seen.add(r[0]); out.append({"role": r[1], "content": r[2], "why": f"relevant {sc:.2f}"})
    return out

def build_system(profile, recalled, base_system):
    parts = []
    if base_system: parts.append(base_system)
    if profile: parts.append("=== WHAT YOU KNOW ABOUT THE USER (core profile) ===\n" + profile)
    if recalled:
        mem = "\n".join(f"[{m['role']}] {m['content'][:600]}" for m in recalled)
        parts.append("=== RELEVANT MEMORIES FROM PAST CONVERSATIONS ===\n" + mem +
                     "\nUse these naturally if relevant. Don't mention that you retrieved them.")
    return "\n\n".join(parts)

def update_profile_async(model):
    def run():
        try:
            c = db()
            msgs = c.execute("SELECT role,content FROM messages ORDER BY id DESC LIMIT 24").fetchall()
            n = c.execute("SELECT COUNT(*) FROM messages WHERE role='assistant'").fetchone()[0]
            c.close()
            if n % PROFILE_EVERY != 0:  # only rebuild on the interval
                return
            convo = "\n".join(f"{r}: {ct[:400]}" for r, ct in reversed(msgs))
            old = get_profile()
            prompt = ("You maintain a concise profile of a user from your conversations. "
                      "Update the profile below with any new stable facts, preferences, projects, "
                      "or goals from the recent exchange. Keep it under 250 words, factual, no fluff.\n\n"
                      f"CURRENT PROFILE:\n{old or '(empty)'}\n\nRECENT CONVERSATION:\n{convo}\n\n"
                      "UPDATED PROFILE:")
            r = ollama_post("/api/generate", {"model": model, "prompt": prompt, "stream": False,
                                              "think": False, "options": {"num_predict": 400}})
            d = json.loads(r.read())
            txt = (d.get("response") or "").strip()
            if txt: set_profile(txt)
        except Exception:
            pass
    threading.Thread(target=run, daemon=True).start()


class H(BaseHTTPRequestHandler):
    def _allowed_origin(self):
        # SUN's GUI runs from file:// (Origin 'null') or localhost. A malicious
        # website has a real http(s) origin -> refuse it. This stops other pages
        # in your browser from reading your memories/profile.
        o = self.headers.get("Origin")
        if o is None or o == "null": return "null"
        if o.startswith("http://localhost") or o.startswith("http://127.0.0.1") or o.startswith("https://localhost"):
            return o
        return None

    def _cors(self):
        allow = self._allowed_origin() or "null"
        self.send_header("Access-Control-Allow-Origin", allow)
        self.send_header("Access-Control-Allow-Methods", "POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")

    def _reject_foreign(self):
        if self._allowed_origin() is None:
            self.send_response(403); self.end_headers(); return True
        return False

    def do_OPTIONS(self):
        self.send_response(204); self._cors(); self.end_headers()

    def do_POST(self):
        if self._reject_foreign(): return
        if not self.path.startswith("/api/chat"):
            self.send_response(404); self._cors(); self.end_headers(); return
        try:
            length = int(self.headers.get("Content-Length", 0))
            req = json.loads(self.rfile.read(length))
        except Exception:
            self.send_response(400); self._cors(); self.end_headers(); return

        messages = req.get("messages", [])
        model = req.get("model", "")
        base_system = ""
        convo = []
        for m in messages:
            if m.get("role") == "system": base_system = m.get("content", "")
            else: convo.append(m)
        last_user = next((m["content"] for m in reversed(convo) if m.get("role") == "user"), "")

        qemb = embed(last_user)
        recalled = retrieve(qemb)
        profile = get_profile()
        sys_text = build_system(profile, recalled, base_system)
        aug = ([{"role": "system", "content": sys_text}] if sys_text else []) + convo

        fwd = dict(req); fwd["messages"] = aug; fwd["stream"] = True

        # respond as a stream
        self.send_response(200)
        self.send_header("Content-Type", "application/x-ndjson")
        self._cors(); self.end_headers()

        # first line: what we recalled (GUI shows this in 'under the hood')
        recap = {"sun_recall": {
            "profile": profile,
            "memories": [{"role": m["role"], "why": m["why"], "text": m["content"][:200]} for m in recalled]
        }}
        try:
            self.wfile.write((json.dumps(recap) + "\n").encode()); self.wfile.flush()
        except Exception:
            pass

        answer = []
        try:
            resp = ollama_post("/api/chat", fwd, stream=True)
            for raw in resp:
                if not raw: continue
                try:
                    self.wfile.write(raw); self.wfile.flush()
                except Exception:
                    break
                try:
                    o = json.loads(raw.decode().strip())
                    if o.get("message", {}).get("content"):
                        answer.append(o["message"]["content"])
                except Exception:
                    pass
        except Exception as e:
            try:
                self.wfile.write((json.dumps({"message": {"content": f"\n[memory-proxy error] {e}"},
                                              "done": True}) + "\n").encode()); self.wfile.flush()
            except Exception:
                pass

        # persist this exchange
        if last_user:
            save("user", last_user, qemb)
        full = "".join(answer)
        if full:
            save("assistant", full, embed(full))
            update_profile_async(model)

    def log_message(self, *a):
        pass


if __name__ == "__main__":
    db().close()
    print(f"S.U.N. memory on http://localhost:{PORT}  (db: {DB.name}, embed: {EMBED_MODEL})")
    ThreadingHTTPServer(("127.0.0.1", PORT), H).serve_forever()
'''

def write_files():
    GUI.write_bytes(base64.b64decode(SUN_HTML_B64))
    SENSORS.write_text(SENSORS_SRC)
    MEMORY.write_text(MEMORY_SRC)

def ensure_psutil():
    try:
        import psutil  # noqa
    except ImportError:
        print("  installing psutil ...")
        subprocess.run([sys.executable, "-m", "pip", "install", "psutil"],
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

def port_open(p):
    with socket.socket() as s:
        s.settimeout(0.3)
        return s.connect_ex(("127.0.0.1", p)) == 0

def wait_ollama():
    for _ in range(40):
        if port_open(OLLAMA_PORT):
            return True
        time.sleep(0.5)
    return False

def list_models():
    try:
        r = urllib.request.urlopen("http://127.0.0.1:" + str(OLLAMA_PORT) + "/api/tags", timeout=5)
        return json.loads(r.read()).get("models", [])
    except Exception:
        return []

def ensure_embed_model():
    if not any(EMBED_MODEL in m.get("name", "") for m in list_models()):
        print("  memory:  pulling " + EMBED_MODEL + " (one-time, ~270MB) ...")
        try:
            subprocess.run(["ollama", "pull", EMBED_MODEL],
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            print("  memory:  ready")
        except Exception:
            print("  memory:  skipped - recall falls back to recent-only")

def ensure_chat_model():
    chat = [m for m in list_models() if EMBED_MODEL not in m.get("name", "")]
    if chat:
        return
    print("\n  You don't have an AI model yet.")
    try:
        ans = input("  Download a small starter model now? (~5GB, one-time) [Y/n] ").strip().lower()
    except Exception:
        ans = "y"
    if ans in ("", "y", "yes"):
        print("  pulling " + STARTER_MODEL + " ... this takes a few minutes, please wait")
        try:
            subprocess.run(["ollama", "pull", STARTER_MODEL])
            print("  model ready")
        except Exception:
            print("  couldn't pull - install one yourself with:  ollama pull llama3.1:8b")
    else:
        print("  ok - pull one yourself any time with:  ollama pull llama3.1:8b")

def start_ollama():
    if port_open(OLLAMA_PORT):
        print("  ollama:  already running")
        print("           (if the GUI says 'ollama offline', quit the Ollama tray icon once, then run this again)")
        return None
    env = os.environ.copy(); env["OLLAMA_ORIGINS"] = "*"
    try:
        p = subprocess.Popen(["ollama", "serve"], env=env,
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except FileNotFoundError:
        print("  ollama:  NOT FOUND - install the free Ollama app from ollama.com first")
        return None
    if wait_ollama():
        print("  ollama:  started")
    return p

def start_helper(name, path, port):
    if port_open(port):
        print("  " + name + ": already running")
        return None
    p = subprocess.Popen([sys.executable, str(path)],
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    for _ in range(12):
        if port_open(port):
            print("  " + name + ": started")
            return p
        time.sleep(0.3)
    print("  " + name + ": started")
    return p

def main():
    print("\n  S U N  -  starting up")
    write_files()
    ensure_psutil()
    if IS_WIN:
        try:
            subprocess.run(["setx", "OLLAMA_ORIGINS", "*"], capture_output=True, check=False)
        except Exception:
            pass
    started = []
    o = start_ollama()
    if o: started.append(o)
    if not wait_ollama():
        print("\n  Ollama isn't running. Install it free from ollama.com, then run this again.\n")
    else:
        ensure_chat_model()
        ensure_embed_model()
        s = start_helper("sensors", SENSORS, SENSOR_PORT)
        if s: started.append(s)
        mm = start_helper("memory ", MEMORY, MEMORY_PORT)
        if mm: started.append(mm)
    time.sleep(1.2)
    print("  gui:     opening in your browser")
    webbrowser.open(GUI.as_uri())
    print("\n  Done. Leave this window open while you use S.U.N.")
    print("  Press Ctrl+C here to shut it down.\n")
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        for p in started:
            try: p.terminate()
            except Exception: pass

if __name__ == "__main__":
    main()
